const response = $input.first().json;
if (!response.id) throw new Error('ClickUp did not return a comment id');
ctx.clickup_comment_id = String(response.id);
ctx.req = { body: decidedMessage(ctx.refs, ctx.action) };
return [{ json: ctx }];

